solution.solution.cpp:
#include <string>
#include <string_view>

class Greeter
{
public:
    std::string greet(std::string_view name) const { return "Hello, " + std::string{ name }; }
};

class ExcitedGreeter : public Greeter
{
public:
    std::string greet(std::string_view name) const { return Greeter::greet(name) + "!!!"; }
};

unitTests:
static_assert(std::is_base_of_v<Greeter, ExcitedGreeter>);
TEST("the base is unchanged") { CHECK_EQ(Greeter{}.greet("Ada"), "Hello, Ada"); }
TEST("the derived class builds on it") { CHECK_EQ(ExcitedGreeter{}.greet("Ada"), "Hello, Ada!!!"); }

